from queueing import payload
def submit(owner, enqueue, mode="all"):
    valid_modes = {"all", "remote", "hybrid", "office"}
    if mode not in valid_modes:
        raise ValueError(f"Invalid mode: {mode!r}. Must be one of {valid_modes}")
    return enqueue(payload(owner, mode))

def execute(task, jobs, mode="all"):
    valid_modes = {"remote", "hybrid", "office"}
    result = []
    for job in jobs:
        job_mode = job.get("mode")
        if job_mode is None or job_mode == "":
            # Legacy jobs with missing/None mode - always included
            result.append(job)
        elif job_mode in valid_modes:
            # Known mode - include if filter matches or mode is "all"
            if mode == "all" or job_mode == mode:
                result.append(job)
        else:
            # Unknown mode - include (stay included for every filter)
            result.append(job)
    return result
